async function walletData(){
  if(!BACKEND_READY){const u=demoUser()||{};const tx=JSON.parse(localStorage.getItem('khadamatiWalletTx')||'[]');const providers=demoProviders().filter(p=>p.userId==='demo'||p.contact===u.phone);const req=u.requestList||[];const spent=req.filter(r=>['held','released'].includes(r.paymentStatus)).reduce((a,r)=>a+Number(r.providerPrice||0),0);const earned=req.filter(r=>['held','released'].includes(r.paymentStatus)&&r.status==='تم التنفيذ').reduce((a,r)=>a+Number(r.providerNet||0),0);const fees=req.filter(r=>['held','released'].includes(r.paymentStatus)).reduce((a,r)=>a+Number(r.platformFee||0),0);return {balance:Number(u.walletBalance||0),spent,earned,fees,tx}}
  const {data:acc,error}=await sb.from('wallet_accounts').select('balance').eq('user_id',sessionUser.id).maybeSingle();if(error)throw error;
  const {data:tx,error:te}=await sb.from('wallet_transactions').select('id,type,amount,note,created_at').eq('user_id',sessionUser.id).order('created_at',{ascending:false}).limit(30);if(te)throw te;
  const {data:req,error:re}=await sb.from('service_requests').select('provider_id,provider_price,platform_fee,provider_net,payment_status,status,providers!inner(user_id)').eq('providers.user_id',sessionUser.id);
  if(re) throw re; const mine=req||[];return {balance:Number(acc?.balance||0),spent:mine.filter(x=>['held','released'].includes(x.payment_status)&&x.status!=='تم التنفيذ').reduce((a,x)=>a+Number(x.provider_price||0),0),earned:mine.filter(x=>x.payment_status==='released'&&x.status==='تم التنفيذ').reduce((a,x)=>a+Number(x.provider_net||0),0),fees:mine.filter(x=>['held','released'].includes(x.payment_status)).reduce((a,x)=>a+Number(x.platform_fee||0),0),tx:tx||[]};
}
function money(n){return Number(n||0).toFixed(2)+' جنيه'}
async function renderWallet(){if(!user())return show('loginPage');show('walletPage');try{const w=await walletData();$('walletBalance').textContent=money(w.balance);$('walletPageBalance').textContent=money(w.balance);$('walletSpent').textContent=money(w.spent);$('walletEarned').textContent=money(w.earned);$('walletFees').textContent=money(w.fees);$('walletTransactions').innerHTML=w.tx.length?w.tx.map(t=>`<div class=\"wallet-tx\"><span>${t.type==='deposit'?'➕':t.type==='payment'?'💳':t.type==='earning'?'📈':'🏦'}</span><div><b>${escapeHtml(t.note||t.type)}</b><small>${formatDate(t.created_at||t.createdAt)}</small></div><strong>${Number(t.amount)>=0?'+':''}${money(t.amount)}</strong></div>`).join(''):'<div class=\"empty-state\"><div>💸</div><h3>لا توجد عمليات</h3><p>استخدم الشحن التجريبي لبدء المحاكاة.</p></div>'}catch(e){toast('تعذر تحميل المحفظة')}}
