let pendingPayment=null;function openCheckout(request){appliedCoupon=null;const price=Number(request.providerPrice||0),fee=Number(request.platformFee||price*0.10),total=price+fee;pendingPayment={...request,total};$('checkoutTitle').textContent='طلب '+request.id+' — '+(request.providerName||'مقدم الخدمة');$('checkoutPrice').textContent=money(price);$('checkoutFee').textContent=money(fee);$('checkoutTotal').textContent=money(total);$('couponCode').value='';$('couponDiscountRow').classList.add('hidden');setMsg('couponMsg','');setMsg('checkoutMsg','');$('checkoutModal').classList.remove('hidden');$('checkoutModal').setAttribute('aria-hidden','false')}
const COUPONS={KHADAMATI10:{type:'percent',value:10,min:100,maxDiscount:100},WELCOME50:{type:'fixed',value:50,min:300,maxDiscount:50}};
async function applyCoupon(){const code=($('couponCode')?.value||'').trim().toUpperCase();if(!pendingPayment)return;let c=null;if(BACKEND_READY){try{const {data,error}=await sb.rpc('validate_coupon',{p_code:code,p_amount:Number(pendingPayment.providerPrice||0)});if(!error&&data?.length)c=data[0]}catch{}}else{c=COUPONS[code];if(c)c={code,type:c.type,value:c.value,min_amount:c.min,max_discount:c.maxDiscount,discount:c.type==='percent'?Math.min(Number(pendingPayment.providerPrice||0)*c.value/100,c.maxDiscount):Math.min(c.value,Number(pendingPayment.providerPrice||0))}}if(!c)return appliedCoupon=null,$('couponDiscountRow').classList.add('hidden'),setMsg('couponMsg','كود الخصم غير صحيح أو منتهي.');if(c.min_amount&&Number(pendingPayment.providerPrice||0)<Number(c.min_amount))return appliedCoupon=null,setMsg('couponMsg',`الحد الأدنى لهذا الكود ${c.min_amount} جنيه.`);const discount=Number(c.discount||0);appliedCoupon={code,discount};$('checkoutDiscount').textContent=money(discount);$('couponDiscountRow').classList.remove('hidden');setMsg('couponMsg',`تم تطبيق الخصم: ${money(discount)} ✓`,true);updateCheckoutTotal()}
function updateCheckoutTotal(){if(!pendingPayment)return;const price=Number(pendingPayment.providerPrice||0),fee=Number(pendingPayment.platformFee||0),discount=Number(appliedCoupon?.discount||0),total=Math.max(0,price+fee-discount);$('checkoutFee').textContent=money(fee);$('checkoutTotal').textContent=money(total);pendingPayment.total=total}
async function payPending(){if(!pendingPayment)return;try{if(!BACKEND_READY){const u=demoUser();const bal=Number(u.walletBalance||0);if(bal<pendingPayment.total)return setMsg('checkoutMsg','الرصيد غير كافٍ. افتح المحفظة واشحن رصيداً تجريبياً.');u.walletBalance=bal-pendingPayment.total;const r=(u.requestList||[]).find(x=>String(x.id)===String(pendingPayment.id));if(r)r.paymentStatus='held';saveDemoUser(u);const tx=JSON.parse(localStorage.getItem('khadamatiWalletTx')||'[]');tx.unshift({type:'payment',amount:-pendingPayment.total,note:'حجز مبلغ الطلب في الوساطة '+pendingPayment.id,createdAt:new Date().toISOString()});localStorage.setItem('khadamatiWalletTx',JSON.stringify(tx))}else{const {error}=await sb.rpc('pay_for_request',{p_request_id:Number(pendingPayment.id)});if(error)throw error}setMsg('checkoutMsg','تم الدفع بنجاح ✅',true);toast('تم تأكيد الدفع');setTimeout(()=>{closeCheckout();showRequests();updateWalletMini()},600)}catch(e){setMsg('checkoutMsg','تعذر تنفيذ الدفع. '+(e.message||''))}}
async function releasePayment(request){try{if(!request||request.status!=='تم التنفيذ')return toast('لا يمكن تأكيد الاستلام قبل اكتمال الطلب');if(request.paymentStatus==='released')return toast('تم تحرير المبلغ بالفعل');if(request.paymentStatus!=='held')return toast('لا يوجد مبلغ محجوز لهذا الطلب');if(!BACKEND_READY){const u=demoUser();const r=(u.requestList||[]).find(x=>String(x.id)===String(request.id));if(r){r.paymentStatus='released';const net=Number(r.providerNet||Math.max(Number(r.providerPrice||0)-Number(r.platformFee||0),0));const tx=JSON.parse(localStorage.getItem('khadamatiWalletTx')||'[]');tx.unshift({type:'earning',amount:net,note:'تحرير أرباح الطلب '+request.id,createdAt:new Date().toISOString()});localStorage.setItem('khadamatiWalletTx',JSON.stringify(tx));saveDemoUser(u)}}else{const {error}=await sb.rpc('release_request_payment',{p_request_id:Number(request.id)});if(error)throw error}toast('تم تأكيد الاستلام وتحرير المبلغ ✅');await showRequests();}catch(e){toast('تعذر تحرير المبلغ: '+(e.message||''))}}
function closeCheckout(){pendingPayment=null;$('checkoutModal').classList.add('hidden');$('checkoutModal').setAttribute('aria-hidden','true')}
async function updateWalletMini(){if(!user()||!$('walletBalance'))return;try{const w=await walletData();$('walletBalance').textContent=money(w.balance)}catch{}}
