async function getProvider(id){const list=await loadProviders();return list.find(x=>String(x.id)===String(id))||null}
async function providerStats(id){if(!BACKEND_READY){const all=demoUser()?.requestList||[];const completed=all.filter(r=>String(r.providerId)===String(id)&&r.status==='تم التنفيذ').length;const ratings=JSON.parse(localStorage.getItem('khadamatiRatings')||'[]').filter(r=>String(r.providerId)===String(id));return {completed,ratings}}const {data,error}=await sb.rpc('get_provider_stats',{p_provider_id:Number(id)});if(error)throw error;const row=(data||[])[0]||{completed:0,reviews:0,average:0};const {data:ratings,error:re}=await sb.from('provider_reviews').select('rating,comment,created_at,profiles(full_name)').eq('provider_id',id).order('created_at',{ascending:false});if(re)throw re;return {completed:Number(row.completed||0),ratings:ratings||[],average:Number(row.average||0)}}
async function showProviderProfile(id){const p=await getProvider(id);if(!p)return toast('مقدم الخدمة غير موجود');trackEvent('provider_view','provider:'+id);profileProvider=p;show('providerProfilePage');$('profileProviderName').textContent=p.name;$('profileProviderTitle').textContent=p.name;$('profileProviderCategory').textContent=p.category;$('profileProviderDesc').textContent=p.description;$('profilePrice').textContent=p.price;try{const st=await providerStats(id);const avg=st.ratings.length?st.ratings.reduce((a,x)=>a+Number(x.rating),0)/st.ratings.length:0;$('profileRating').textContent='⭐ '+Number(st.average||avg).toFixed(1);$('profileCompleted').textContent=st.completed;$('profileReviews').textContent=st.ratings.length;$('reviewsList')?.replaceChildren();$('profileReviewsList').innerHTML=st.ratings.length?st.ratings.map(r=>`<article class="review-card"><div>⭐ ${escapeHtml(r.rating)}/5</div><b>${escapeHtml(r.profiles?.full_name||'عميل')}</b><p>${escapeHtml(r.comment||'تقييم بدون تعليق')}</p><small>${formatDate(r.created_at)}</small></article>`).join(''):'<div class="empty-state"><div>⭐</div><h3>لا توجد تقييمات بعد</h3><p>كن أول عميل يقيّم هذه الخدمة.</p></div>'}catch(e){$('profileRating').textContent='⭐ 0.0';$('profileReviewsList').innerHTML='<div class="empty-state"><p>تعذر تحميل التقييمات.</p></div>'} }
async function openRatingForRequest(r){selectedRating=0;$('ratingComment').value='';$('ratingRequestTitle').textContent=(r.providerName||'مقدم الخدمة')+' — '+r.service;$('ratingMsg').textContent='';document.querySelectorAll('#ratingStars button').forEach(b=>b.classList.remove('selected'));$('ratingModal').classList.remove('hidden');$('ratingModal').setAttribute('aria-hidden','false');$('submitRating').dataset.requestId=r.id;$('submitRating').dataset.providerId=r.providerId||'';}
async function loadProviders(){
  if(!BACKEND_READY)return demoProviders();
  const {data,error}=await sb.from('providers').select('id,name,category,description,price,contact,user_id,commission_rate,created_at').eq('active',true).order('created_at',{ascending:false});
  if(error)throw error; return data||[];
}
function renderProviders(list){
  const box=$('providersList'); if(!box)return;
  const q=($('providerSearch')?.value||'').trim().toLowerCase(), cat=$('providerCategory')?.value||'';
  const filtered=list.filter(p=>(!cat||p.category===cat)&&(!q||[p.name,p.category,p.description,p.contact].some(v=>String(v||'').toLowerCase().includes(q))));
  box.innerHTML=filtered.length?filtered.map(p=>`<article class="provider-card"><div class="provider-avatar">🧑‍💼</div><span class="provider-category">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p class="provider-desc">${escapeHtml(p.description)}</p><div class="provider-meta"><span>⭐ ${Number(p.avg_rating||0).toFixed(1)} (${Number(p.review_count||0)})</span><span class="provider-contact">${escapeHtml(p.contact||'')}</span></div><div class="provider-price">${escapeHtml(p.price)} جنيه <small>يبدأ من</small></div><div class="provider-actions"><button class="secondary profile-btn" data-profile="${escapeHtml(p.id)}">الملف والتقييمات</button><button class="primary" data-provider="${escapeHtml(p.id)}">اطلب الآن</button></div></article>`).join(''):'<div class="empty-state"><div>🔎</div><h3>لا توجد نتائج</h3><p>جرّب كلمة بحث أو تصنيفاً مختلفاً.</p></div>';
  box.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>chooseProvider(b.dataset.provider));box.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>showProviderProfile(b.dataset.profile));
}
