let adminCache={requests:[],users:[],providers:[],withdrawals:[],transactions:[]};
function adminMoney(n){return money(n)}
async function loadAdminData(){
  if(!BACKEND_READY){
    const u=demoUser()||{}; const requests=(u.requestList||[]).map(r=>({...r,userName:u.name,userPhone:u.phone}));
    const providers=demoProviders().map(p=>({...p,completed:requests.filter(r=>String(r.providerId)===String(p.id)&&r.status==='تم التنفيذ').length}));
    const transactions=JSON.parse(localStorage.getItem('khadamatiWalletTx')||'[]');
    return {requests,users:u.name?[{id:'demo',full_name:u.name,phone:u.phone,role:u.role||'user'}]:[],providers,withdrawals:JSON.parse(localStorage.getItem('khadamatiWithdrawals')||'[]'),transactions};
  }
  const [rq,us,pv,wd,tx]=await Promise.all([
    sb.from('service_requests').select('id,user_id,service,note,status,created_at,provider_id,provider_price,platform_fee,provider_net,payment_status,profiles(full_name,phone),providers(name)').order('created_at',{ascending:false}),
    sb.from('profiles').select('id,full_name,phone,role,created_at').order('created_at',{ascending:false}),
    sb.from('providers').select('id,user_id,name,category,description,price,active,commission_rate').order('created_at',{ascending:false}),
    sb.from('withdrawal_requests').select('id,user_id,amount,method,status,created_at,profiles(full_name,phone)').order('created_at',{ascending:false}),
    sb.from('wallet_transactions').select('id,user_id,type,amount,request_id,note,created_at,profiles(full_name,phone)').order('created_at',{ascending:false}).limit(100)
  ]);
  for(const x of [rq,us,pv,wd,tx])if(x.error)throw x.error;
  return {requests:(rq.data||[]).map(x=>({...x,userName:x.profiles?.full_name||'',userPhone:x.profiles?.phone||'',providerName:x.providers?.name||'',createdAt:x.created_at,providerPrice:x.provider_price,platformFee:x.platform_fee,paymentStatus:x.payment_status,providerNet:x.provider_net})),users:us.data||[],providers:pv.data||[],withdrawals:wd.data||[],transactions:tx.data||[]};
}
function adminFilter(arr,q,fields){if(!q)return arr;return arr.filter(x=>fields.some(k=>String(x[k]??'').toLowerCase().includes(q)))}
function renderAdminStats(d){
  const r=d.requests; const held=r.filter(x=>x.paymentStatus==='held').reduce((a,x)=>a+Number(x.providerPrice||0),0); const released=r.filter(x=>x.paymentStatus==='released').reduce((a,x)=>a+Number(x.providerPrice||0),0); const refunded=r.filter(x=>x.paymentStatus==='refunded').reduce((a,x)=>a+Number(x.providerPrice||0),0); const revenue=r.filter(x=>['held','released'].includes(x.paymentStatus)).reduce((a,x)=>a+Number(x.platformFee||0),0);
  $('adminTotalRequests').textContent=r.length; $('adminPending').textContent=r.filter(x=>x.status==='قيد المراجعة').length; $('adminUsers').textContent=d.users.length; $('adminRevenue').textContent=adminMoney(revenue); $('adminHeld').textContent=adminMoney(held); $('adminReleased').textContent=adminMoney(released); $('adminRefunded').textContent=adminMoney(refunded); $('adminWithdrawals').textContent=d.withdrawals.filter(x=>x.status==='قيد المراجعة').length;
}
function renderAdminOverview(d,q){
  const growth=d.growth; if(growth){const el=$('adminGrowthSummary');if(el)el.innerHTML=`<span>👀 زيارات مقدمين: ${growth.provider_views||0}</span><span>📄 زيارات خدمات: ${growth.service_views||0}</span><span>📝 طلبات من الأحداث: ${growth.requests_created||0}</span>`;}
  const recent=adminFilter(d.requests,q,['id','service','userName','status']).slice(0,6); $('adminRecentRequests').innerHTML=recent.length?recent.map(r=>`<div class="admin-list-row"><div><b>#${escapeHtml(r.id)}</b><small>${escapeHtml(r.service)} · ${escapeHtml(r.userName)}</small></div><span class="status ${statusClass(r.status)}">${escapeHtml(r.status)}</span></div>`).join(''):'<p class="muted">لا توجد بيانات.</p>';
  const top=[...d.providers].sort((a,b)=>Number(b.completed||0)-Number(a.completed||0)).slice(0,6); $('adminTopProviders').innerHTML=top.length?top.map(p=>`<div class="admin-list-row"><div><b>🧑‍💼 ${escapeHtml(p.name)}</b><small>${escapeHtml(p.category||'')} · يبدأ من ${adminMoney(p.price)}</small></div><strong>${Number(p.completed||0)} مكتملة</strong></div>`).join(''):'<p class="muted">لا توجد خدمات منشورة.</p>';
}
function renderAdminRequests(d,q){const f=adminFilter(d.requests,q,['id','service','userName','userPhone','status','note']);$('adminRequestsList').innerHTML=f.length?f.map(r=>`<article class="admin-request"><div class="admin-request-main"><div class="request-top"><span class="request-id">#${escapeHtml(r.id)}</span><span class="status ${statusClass(r.status)}">${escapeHtml(r.status)}</span></div><h3>${serviceInfo[r.service]?.[0]||'📋'} ${escapeHtml(r.service)}</h3><p>${escapeHtml(r.note)}</p><div class="admin-meta"><span>👤 ${escapeHtml(r.userName)}</span><span>📱 ${escapeHtml(r.userPhone)}</span><span>💰 ${r.providerPrice?adminMoney(r.providerPrice):'بدون دفع'}</span><span>🕒 ${formatDate(r.createdAt)}</span></div>${r.providerName?`<div class="admin-meta"><span>🧑‍💼 ${escapeHtml(r.providerName)}</span><span>🔐 ${escapeHtml(r.paymentStatus||'غير مطلوب')}</span></div>`:''}</div><div class="status-actions"><label>تغيير الحالة</label><select data-id="${escapeHtml(r.id)}" class="status-select"><option ${r.status==='قيد المراجعة'?'selected':''}>قيد المراجعة</option><option ${r.status==='جاري التنفيذ'?'selected':''}>جاري التنفيذ</option><option ${r.status==='تم التنفيذ'?'selected':''}>تم التنفيذ</option><option ${r.status==='ملغي'?'selected':''}>ملغي</option></select>${r.paymentStatus==='held'?`<button class="danger-btn refund-btn" data-id="${escapeHtml(r.id)}">↩️ استرداد المبلغ</button>`:''}</div></article>`).join(''):'<div class="empty-state"><div>📭</div><h3>لا توجد طلبات</h3><p>غيّر البحث أو انتظر طلبات جديدة.</p></div>';bindAdminActions()}
function renderAdminUsers(d,q){const f=adminFilter(d.users,q,['full_name','phone','role']);$('adminUsersList').innerHTML=f.length?f.map(u=>`<article class="admin-user"><div class="user-avatar">👤</div><div><b>${escapeHtml(u.full_name||'بدون اسم')}</b><small>${escapeHtml(u.phone||'')}</small></div><strong>${u.role==='admin'?'🛡️ إدارة':'مستخدم'}</strong></article>`).join(''):'<div class="empty-state"><div>👥</div><h3>لا يوجد مستخدمون</h3></div>'}
function renderAdminProviders(d,q){const f=adminFilter(d.providers,q,['name','category','description']);$('adminProvidersList').innerHTML=f.length?f.map(p=>`<article class="admin-user"><div class="user-avatar">🧑‍💼</div><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.category||'أخرى')} · ${adminMoney(p.price)} · عمولة ${Number(p.commission_rate||10)}%</small></div><strong>${p.active===false?'موقوف':'نشط'}</strong></article>`).join(''):'<div class="empty-state"><div>🧑‍💼</div><h3>لا يوجد مقدمو خدمات</h3></div>'}
function renderAdminFinance(d,q){
  const rows=[...d.withdrawals.map(x=>({...x,rowType:'withdrawal',createdAt:x.created_at||x.createdAt})),...d.transactions.map(x=>({...x,rowType:'transaction',createdAt:x.created_at||x.createdAt}))].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const f=adminFilter(rows,q,['id','userName','method','status','type','note']);$('adminFinanceList').innerHTML=f.length?f.slice(0,80).map(x=>x.rowType==='withdrawal'?`<article class="finance-row"><div><b>🏦 طلب سحب #${escapeHtml(x.id)}</b><small>${escapeHtml(x.profiles?.full_name||x.userName||'')} · ${escapeHtml(x.method||'')}</small></div><strong>${adminMoney(x.amount)}</strong><select class="withdraw-status" data-id="${escapeHtml(x.id)}"><option ${x.status==='قيد المراجعة'?'selected':''}>قيد المراجعة</option><option ${x.status==='تم التحويل'?'selected':''}>تم التحويل</option><option ${x.status==='مرفوض'?'selected':''}>مرفوض</option></select></article>`:`<article class="finance-row"><div><b>${x.type==='earning'?'📈 أرباح':x.type==='payment'?'💳 دفع':x.type==='refund'?'↩️ استرداد':x.type==='fee'?'🏦 عمولة':'💰 عملية'}</b><small>${escapeHtml(x.profiles?.full_name||x.userName||'')} · ${escapeHtml(x.note||'')}</small></div><strong>${adminMoney(x.amount)}</strong></article>`).join(''):'<div class="empty-state"><div>💰</div><h3>لا توجد عمليات مالية</h3></div>';document.querySelectorAll('.withdraw-status').forEach(s=>s.onchange=()=>updateWithdrawal(s.dataset.id,s.value))}
function bindAdminActions(){document.querySelectorAll('.status-select').forEach(s=>s.onchange=()=>updateStatus(s.dataset.id,s.value));document.querySelectorAll('.refund-btn').forEach(b=>b.onclick=()=>refundRequest(b.dataset.id))}
