// V3.5 — مساعد خدماتي الذكي (محرك ترشيح محلي آمن، بدون مفاتيح سرية داخل المتصفح)
const aiState={step:0,answers:{}};
const aiQuestions=[
 {key:'goal',title:'إيه اللي محتاج تعمله؟',options:[['website','عمل موقع أو صفحة هبوط'],['marketing','تسويق أو إعلانات'],['design','تصميم صور أو هوية'],['code','برمجة أو تعديل برنامج'],['maintenance','صيانة أو إصلاح'],['other','خدمة أخرى']]},
 {key:'budget',title:'ميزانيتك التقريبية؟',options:[['low','حتى 200 جنيه'],['mid','من 200 إلى 500 جنيه'],['high','أكثر من 500 جنيه'],['unknown','مش عارف لسه']]},
 {key:'speed',title:'إمتى محتاج الخدمة؟',options:[['urgent','بسرعة'],['normal','خلال أيام'],['flex','مش مستعجل']]},
];
function openAiAssistant(){if(!user())return show('loginPage');aiState.step=0;aiState.answers={};$('aiResult').classList.add('hidden');$('aiNextBtn').textContent='التالي';$('aiBackBtn').classList.add('hidden');$('aiModal').classList.remove('hidden');$('aiModal').setAttribute('aria-hidden','false');renderAiStep()}
function closeAiAssistant(){$('aiModal').classList.add('hidden');$('aiModal').setAttribute('aria-hidden','true')}
function renderAiStep(){const q=aiQuestions[aiState.step];$('aiStepHint').textContent=`السؤال ${aiState.step+1} من ${aiQuestions.length}`;$('aiWizard').innerHTML=`<div class="ai-question"><h3>${escapeHtml(q.title)}</h3>${q.options.map(([v,l])=>`<label class="ai-option ${aiState.answers[q.key]===v?'selected':''}"><input type="radio" name="ai-${q.key}" value="${v}" ${aiState.answers[q.key]===v?'checked':''}> <span>${escapeHtml(l)}</span></label>`).join('')}</div>`;document.querySelectorAll('.ai-option').forEach(o=>o.onclick=()=>{document.querySelectorAll('.ai-option').forEach(x=>x.classList.remove('selected'));o.classList.add('selected');o.querySelector('input').checked=true});$('aiBackBtn').classList.toggle('hidden',aiState.step===0)}
function aiCategory(goal){return goal==='marketing'?'تسويق':goal==='design'?'تصميم':goal==='code'||goal==='website'?'برمجة':goal==='maintenance'?'صيانة':'أخرى'}
function aiScoreProvider(p,a){let score=0;const cat=aiCategory(a.goal);if(p.category===cat)score+=60;if(a.budget==='low'&&Number(p.price)<=200)score+=25;if(a.budget==='mid'&&Number(p.price)<=500)score+=20;if(a.budget==='high')score+=15;if(a.budget==='unknown')score+=10;if(a.speed==='urgent')score+=5;score+=Math.min(10,Number(p.rating||0)*2);return score}
function aiRecommend(){const a=aiState.answers,cat=aiCategory(a.goal),providers=demoProviders().map(p=>({...p,score:aiScoreProvider(p,a)})).sort((x,y)=>y.score-x.score);const top=providers.filter(p=>p.category===cat).slice(0,3);const picks=(top.length?top:providers).slice(0,3);$('aiStepHint').textContent='الترشيح جاهز';$('aiWizard').innerHTML='';$('aiNextBtn').textContent='ابدأ طلبًا جديدًا';$('aiResult').classList.remove('hidden');$('aiResult').innerHTML=`<h3>🎯 أنسب تصنيف لك: ${escapeHtml(cat)}</h3><p class="muted">بناءً على هدفك وميزانيتك والسرعة، هذه أفضل الترشيحات المتاحة الآن.</p><div class="ai-recommendations">${picks.map(p=>`<div class="ai-provider"><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.category)} · يبدأ من ${Number(p.price||0)} جنيه${p.rating?' · ⭐ '+Number(p.rating).toFixed(1):''}</small></div><button class="secondary ai-pick" data-id="${escapeHtml(p.id)}">عرض المقدم</button></div>`).join('')}</div><p class="muted" style="margin-bottom:0">ملاحظة: هذا الترشيح آلي داخل الموقع، ويمكن لاحقًا ربطه بخدمة ذكاء اصطناعي حقيقية من خادم آمن.</p>`;document.querySelectorAll('.ai-pick').forEach(b=>b.onclick=()=>{closeAiAssistant();openProviderProfile(b.dataset.id)})}
function aiNext(){if(aiState.step<aiQuestions.length){const q=aiQuestions[aiState.step],sel=document.querySelector(`input[name="ai-${q.key}"]:checked`);if(!sel)return toast('اختار إجابة الأول 👌');aiState.answers[q.key]=sel.value;if(aiState.step===aiQuestions.length-1){aiState.step=aiQuestions.length;aiRecommend()}else{aiState.step++;renderAiStep()}}else{closeAiAssistant();show('providersPage');renderProviders()} }
function aiBack(){if(aiState.step>0&&aiState.step<aiQuestions.length){aiState.step--;renderAiStep()}}
$('aiAssistantBtn')?.addEventListener('click',openAiAssistant);$('closeAiModal')?.addEventListener('click',closeAiAssistant);$('aiNextBtn')?.addEventListener('click',aiNext);$('aiBackBtn')?.addEventListener('click',aiBack);
document.querySelectorAll('.service[data-service-slug]').forEach(b=>b.addEventListener('click',()=>openPublicService(b.dataset.serviceSlug)));
document.querySelectorAll('.admin-tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');renderAdmin()});$('adminSearch').oninput=renderAdmin;

