if(BACKEND_READY){$('backendStatus').textContent='الوضع الحقيقي جاهز للاتصال بقاعدة البيانات.';$('backendStatus').classList.add('success-msg');sb.auth.getSession().then(async({data})=>{if(data.session){try{await loadProfile();notificationChannel&&sb.removeChannel(notificationChannel);notificationChannel=subscribeNotifications();showHome()}catch{show('loginPage')}}else if(!handlePublicHash())showPublic()});sb.auth.onAuthStateChange(async()=>{try{await loadProfile();notificationChannel&&sb.removeChannel(notificationChannel);notificationChannel=subscribeNotifications();if(sessionUser)renderNotifications()}catch{}})}else{seedDemoNotifications();if(currentDemo())showHome();else if(!handlePublicHash())showPublic()}

window.addEventListener('hashchange',handlePublicHash);
